import { type Damage, settleClaim } from "./claims";
import type { InsuredItem } from "./insured-item";
import { openPolicy, type Policy } from "./policy";
import { type Customer, isAfterFirstQuote, quotePremium } from "./premium";

export type { InsuredItem } from "./insured-item";

export interface QuoteStep {
  op: "quote";
  items: InsuredItem[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export interface Scenario {
  customer: Customer;
  steps: (QuoteStep | ClaimStep)[];
}

export interface StepResult {
  premium?: number;
  payout?: number;
  remainingCap?: number;
}

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  const policies = new Map<number, Policy>();
  let quotesSoFar = 0;
  const results = scenario.steps.map((step, index): StepResult => {
    if (step.op === "claim") return settleClaim(step.incident.damages, policies.get(step.policy) as Policy);
    policies.set(index, openPolicy(step.items));
    return { premium: quotePremium(step.items, scenario.customer, isAfterFirstQuote(quotesSoFar++)) };
  });
  return { results };
}
import type { InsuredItem } from "./insured-item";
import { drawFromCap, type Policy } from "./policy";
import { reimbursement } from "./reimbursement";

export interface Damage {
  itemType: string;
  amount: number;
}

// Payouts are rounded down to whole G, in MHPCO's favor.
function roundPayoutInMhpcoFavor(exactPayout: number): number {
  return Math.floor(exactPayout);
}

interface DamagedItem {
  damage: Damage;
  insuredItem: InsuredItem;
}

// Each reported damage refers to the next not-yet-damaged insured item of its type, in reporting order.
function matchDamagesToInsuredItems(damages: Damage[], policy: Policy): DamagedItem[] {
  const undamagedItems = [...policy.items];
  return damages.map((damage) => {
    const index = undamagedItems.findIndex((item) => item.type === damage.itemType);
    return { damage, insuredItem: undamagedItems.splice(index, 1)[0] };
  });
}

function totalReimbursement(damages: Damage[], policy: Policy): number {
  return matchDamagesToInsuredItems(damages, policy).reduce(
    (sum, { damage, insuredItem }) => sum + reimbursement(damage.amount, insuredItem),
    0,
  );
}

export function settleClaim(damages: Damage[], policy: Policy): { payout: number; remainingCap: number } {
  const payout = drawFromCap(policy, roundPayoutInMhpcoFavor(totalReimbursement(damages, policy)));
  return { payout, remainingCap: policy.remainingCap };
}
export interface InsuredItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}
import type { InsuredItem } from "./insured-item";
import { unitInsuranceValue } from "./price-list";

// A policy's payout cap: the total payout per policy is capped at twice the insurance sum.
const CAP_FACTOR = 2;

export interface Policy {
  items: InsuredItem[];
  remainingCap: number;
}

// The insurance sum uses each item's price-list insurance value; premium modifiers such as curses do not change it.
function insuranceSum(items: InsuredItem[]): number {
  return items.reduce((sum, item) => sum + unitInsuranceValue(item.type), 0);
}

export function openPolicy(items: InsuredItem[]): Policy {
  return { items, remainingCap: CAP_FACTOR * insuranceSum(items) };
}

// Pays out at most what is left of the policy's cap and deducts the payout from it.
export function drawFromCap(policy: Policy, payout: number): number {
  const cappedPayout = Math.min(payout, policy.remainingCap);
  policy.remainingCap -= cappedPayout;
  return cappedPayout;
}
import type { InsuredItem } from "./insured-item";
import { isComponent, unitBasePremium } from "./price-list";

export interface Customer {
  yearsWithMHPCO: number;
}

const PROCESSING_FEE = 5;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const FOLLOW_UP_DISCOUNT_PERCENT = 15;
const LOYALTY_YEARS = 2;
const LOYALTY_DISCOUNT_PERCENT = 20;
const CURSE_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const PERCENT = 100;
// Amounts are kept in hundredths of a G so percentages stay exact until the final rounding.
const HUNDREDTHS_PER_G = 100;

function countAlikeItems(items: InsuredItem[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  return counts;
}

function isBuildingBlock(type: string, count: number): boolean {
  return isComponent(type) && count === BLOCK_SIZE;
}

function basePremiumForAlikeItems(type: string, count: number): number {
  return isBuildingBlock(type, count) ? BLOCK_BASE_PREMIUM : count * unitBasePremium(type);
}

function policyBasePremium(items: InsuredItem[]): number {
  let sum = 0;
  for (const [type, count] of countAlikeItems(items)) sum += basePremiumForAlikeItems(type, count);
  return sum;
}

function inHundredths(amountInG: number): number {
  return amountInG * HUNDREDTHS_PER_G;
}

function roundPremiumInMhpcoFavor(amountInHundredths: number): number {
  return Math.ceil(amountInHundredths / HUNDREDTHS_PER_G);
}

function percentOf(amount: number, percent: number): number {
  return (amount * percent) / PERCENT;
}

function isLongStandingCustomer(customer: Customer): boolean {
  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
}

function loyaltyDiscountInHundredths(policyBaseInHundredths: number, customer: Customer): number {
  return isLongStandingCustomer(customer) ? percentOf(policyBaseInHundredths, LOYALTY_DISCOUNT_PERCENT) : 0;
}

// Customers receive the follow-up discount on each contract after their first quote in the scenario.
export function isAfterFirstQuote(quoteIndex: number): boolean {
  return quoteIndex > 0;
}

function followUpDiscountInHundredths(policyBaseInHundredths: number, isFollowUpContract: boolean): number {
  return isFollowUpContract ? percentOf(policyBaseInHundredths, FOLLOW_UP_DISCOUNT_PERCENT) : 0;
}

// Policy-wide modifiers apply to the policy base premium (the sum of all item base premiums).
function policyModifiersInHundredths(
  policyBaseInHundredths: number,
  customer: Customer,
  isFollowUpContract: boolean,
): number {
  return (
    percentOf(policyBaseInHundredths, FIRST_INSURANCE_SURCHARGE_PERCENT) -
    loyaltyDiscountInHundredths(policyBaseInHundredths, customer) -
    followUpDiscountInHundredths(policyBaseInHundredths, isFollowUpContract)
  );
}

